import React, { useState } from "react";
import Login from "./components/login";
import IncomeCategory from "./components/IncomeCategory";
import Questionnaire from "./components/Questionnaire";
import SpendingPriority from "./components/SpendingPriority";
import BudgetLimits from "./components/BudgetLimits";
import Dashboard from "./components/Dashboard";

function App() {
  const [step, setStep] = useState(0);

  const [incomeCategory, setIncomeCategory] = useState("");
  const [questionnaire, setQuestionnaire] = useState({});
  const [spendingPriorities, setSpendingPriorities] = useState({});
  const [selectedCategories, setSelectedCategories] = useState([]); // 🔥 NEW

  const handleFinalSave = async (limits) => {
  const finalData = {
    incomeCategory,
    questionnaire,
    spendingPriority: spendingPriorities,
    budgetLimits: limits
  };

  try {
    const res = await fetch("http://localhost:5000/api/userdata/save", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify(finalData)
    });

    const data = await res.json();

    if (data.success) {
      alert("Data saved successfully!");
      return true;   // ✅ ADD THIS
    } else {
      alert("Error saving data");
      return false;
    }
  } catch (err) {
    console.error(err);
    alert("Server error");
    return false;
  }
};

return (
  <div className="app-container">
    {step === 0 && <Login onLogin={() => setStep(1)} />}

    {step === 1 && (
      <IncomeCategory
        onNext={(data) => {
          setIncomeCategory(data);
          setStep(2);
        }}
      />
    )}

    {step === 2 && (
      <Questionnaire
        onNext={(data) => {
          setQuestionnaire(data);
          setStep(3);
        }}
      />
    )}

    {step === 3 && (
      <SpendingPriority
        onNext={(filteredCategories) => {
          setSelectedCategories(filteredCategories);
          setSpendingPriorities(filteredCategories);
          setStep(4);
        }}
      />
    )}

   {step === 4 && (
  <BudgetLimits
    selectedCategories={selectedCategories}   // ✅ ADD THIS
    onNext={async (limits) => {
      await handleFinalSave(limits);
      setStep(5);
    }}
  />
)}

{step === 5 && <Dashboard />}
  </div>
);
}

export default App;
